--- /dev/null
+++ b/rust/fsl-runtime/tests/reviewgraphen_generated_calibration_19.rs
@@ -0,0 +1,32 @@
+// SPDX-License-Identifier: Apache-2.0
+
+use fsl_core::{FsResolver, build_model, parse_kernel_source, parse_refinement};
+use fsl_runtime::check_refinement;
+
+fn build(source: &str) -> fsl_core::KernelModel {
+    let kernel =
+        parse_kernel_source(source, &FsResolver::new(std::env::temp_dir())).expect("parse model");
+    build_model(kernel).expect("build model")
+}
+
+#[test]
+fn reviewgraphen_generated_regression() {
+    let implementation = build(
+        "spec Impl { state { slots: Map<Bool, Bool> } init { slots[true] = true } action stay() { slots[true] = true } }",
+    );
+    let abstraction = build(
+        "spec Abs { state { ok: Bool } init { ok = true } action stay() { ok = ok } }",
+    );
+    let refinement = parse_refinement(
+        "refinement R { impl Impl abs Abs map ok = not slots[false] action stay() -> stay() }",
+        &implementation,
+        &abstraction,
+    )
+    .expect("parse refinement");
+
+    let result = check_refinement(&implementation, &abstraction, &refinement, 0)
+        .expect("check refinement");
+    let failure = result.failure.expect("unwritten map entry must be explored");
+    assert_eq!(failure.kind, "abs_state_mismatch");
+    assert_eq!(failure.at.as_deref(), Some("init"));
+}
